// 仅供本轮m414独占性能库：直接构造合法关联，不作为正式购买/退款端到端证据。
import {Client} from 'pg';
import {createHash} from 'node:crypto';
export const performanceId=(kind:string,n:number)=>{const hash=createHash('md5').update('m414-perf-'+kind+'-'+n).digest('hex'),h=hash.slice(0,12)+'4'+hash.slice(13,16)+'8'+hash.slice(17);return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20);};
export async function seedReportingPerformance(employeeId:string,settingId:string){
  if(process.env.NODE_ENV!=='test'||!/^\/m414_[a-f0-9]{32}_test$/.test(new URL(process.env.DATABASE_URL!).pathname))throw new Error('性能夹具仅允许m414本轮独占库');
  const db=new Client({connectionString:process.env.DATABASE_URL});await db.connect();
  const identity=(kind:string,n:string)=>`overlay(overlay(md5('m414-perf-${kind}-'||(${n})::text) placing '4' from 13 for 1) placing '8' from 17 for 1)::uuid`;
  try{
    await db.query('BEGIN');
    await db.query(`CREATE TEMP TABLE perf_rows AS SELECT n,${identity('order','n')} order_id,${identity('quote','n')} quote_id,${identity('customer','n%1000+1')} customer_id,${identity('sku','n%1000+1')} sku_id,${identity('product','n%1000+1')} product_id,${identity('payment','n')} payment_id,${identity('sale','n')} sale_id,${identity('refund','n')} refund_id,${identity('task','n')} task_id,now()-((n%60+1)||' days')::interval AS created_at FROM generate_series(1,100000) n`);
    await db.query(`INSERT INTO customer(id,phone,nickname,password_hash,created_at,updated_at) SELECT ${identity('customer','n')},'188'||lpad(n::text,8,'0'),'性能夹具顾客','不可用于登录的性能占位',now()-(n%60||' days')::interval,now() FROM generate_series(1,1000) n`);
    await db.query(`INSERT INTO product(id,product_code,name,status,created_by_id,updated_by_id,updated_at) SELECT ${identity('product','n')},'PERF-SPU-'||n,'独占性能服装','ON_SALE',$1,$1,now() FROM generate_series(1,1000) n`,[employeeId]);
    await db.query(`INSERT INTO sku(id,product_id,code,combination_signature,price_cents,cost_cents,updated_at) SELECT ${identity('sku','n')},${identity('product','n')},'PERF-SKU-'||n,'DEFAULT',10000,4000,now() FROM generate_series(1,1000) n`);
    await db.query(`INSERT INTO inventory_balance(sku_id,available,reserved,warning_threshold,updated_at) SELECT ${identity('sku','n')},n%20,0,10,now() FROM generate_series(1,1000) n`);
    await db.query(`INSERT INTO checkout_quote(id,customer_id,address_id_snapshot,address_version,address_snapshot,setting_version_id,pricing_rule_snapshot,goods_amount_cents,shipping_fee_cents,payable_cents,created_at,expires_at) SELECT quote_id,customer_id,${identity('address','n')},0,'{}',$1,'{}',10000,0,10000,created_at,created_at+interval '30 minutes' FROM perf_rows`,[settingId]);
    await db.query(`INSERT INTO "order"(id,number,customer_id,quote_id,status,goods_amount_cents,shipping_fee_cents,payable_cents,receiver,phone,province,city,district,detail,shipping_rule_snapshot,payment_rule_snapshot,setting_version_id,payment_deadline,paid_at,actual_handover_at,completed_at,created_at,updated_at) SELECT order_id,'PERF-O-'||n,customer_id,quote_id,CASE WHEN n%20=0 THEN 'REFUNDED' WHEN n%20=1 THEN 'WAIT_PAYMENT' WHEN n%20 IN(2,3) THEN 'WAIT_SHIPMENT' WHEN n%20=4 THEN 'SHIPPED' ELSE 'COMPLETED' END,10000,0,10000,'性能夹具收件人','01000000000','测试省','测试市','测试区','独占性能资料','{}','{}',$1,created_at+interval '30 minutes',CASE WHEN n%20<>1 THEN created_at+interval '1 minute' END,CASE WHEN n%20=4 OR n%20>=5 THEN created_at+interval '2 minutes' END,CASE WHEN n%20>=5 THEN created_at+interval '3 minutes' END,created_at,created_at FROM perf_rows`,[settingId]);
    await db.query(`INSERT INTO order_item(id,order_id,sku_id,product_id,product_name_snapshot,product_code_snapshot,sku_code_snapshot,spec_snapshot,unit_price_cents,quantity,line_amount_cents) SELECT ${identity('item','n')},order_id,sku_id,product_id,'性能服装','PERF-SPU-'||(n%1000+1),'PERF-SKU-'||(n%1000+1),'[]',10000,1,10000 FROM perf_rows`);
    await db.query(`INSERT INTO payment(id,number,order_id,amount_cents,paid_at,actor_customer_id,request_id) SELECT payment_id,'PERF-P-'||n,order_id,10000,created_at+interval '1 minute',customer_id,${identity('request','n')}::text FROM perf_rows WHERE n%20<>1`);
    await db.query(`INSERT INTO after_sale(id,number,order_id,customer_id,payment_id,type,status,reason_code,application_description,current_material_version_id,requested_refund_amount,created_at) SELECT sale_id,'PERF-AS-'||n,order_id,customer_id,payment_id,'REFUND_ONLY',CASE WHEN n%20=0 THEN 'WAIT_REFUND' ELSE 'REFUND_FAILED' END,'OTHER','明确标注的性能关联夹具',${identity('material','n')},10000,created_at+interval '4 minutes' FROM perf_rows WHERE n%20 IN(0,5)`);
    await db.query(`INSERT INTO after_sale_material_version(id,after_sale_id,version_no,description,submitted_by_customer_id,created_at) SELECT ${identity('material','n')},sale_id,1,'性能关联材料',customer_id,created_at+interval '4 minutes' FROM perf_rows WHERE n%20 IN(0,5)`);
    await db.query(`INSERT INTO task_stage_cursor(id,business_type,business_id,stage,last_round,updated_at) SELECT ${identity('cursor','n')},'AFTER_SALE',sale_id,'REFUND_PROCESS',1,now() FROM perf_rows WHERE n%20 IN(0,5)`);
    await db.query(`INSERT INTO task(id,cursor_id,business_type,business_id,stage,round,entry_key,required_permissions,status,assignee_id,started_at,rule_snapshot,closed_at,updated_at) SELECT task_id,${identity('cursor','n')},'AFTER_SALE',sale_id,'REFUND_PROCESS',1,'perf-'||n,'["after-sale.refund.execute"]',CASE WHEN n%20=0 THEN 'COMPLETED'::"TaskStatus" ELSE 'CLAIMED'::"TaskStatus" END,CASE WHEN n%20<>0 THEN $1::uuid END,created_at+interval '4 minutes','{}',CASE WHEN n%20=0 THEN created_at+interval '5 minutes' END,now() FROM perf_rows WHERE n%20 IN(0,5)`,[employeeId]);
    await db.query(`INSERT INTO refund(id,refund_no,payment_id,order_id,after_sale_id,amount_cents,currency,channel,status,created_at,updated_at) SELECT refund_id,'PERF-R-'||n,payment_id,order_id,sale_id,10000,'CNY','SIMULATED','FAILED',created_at+interval '5 minutes',created_at+interval '5 minutes' FROM perf_rows WHERE n%20 IN(0,5)`);
    await db.query(`INSERT INTO refund_attempt(id,refund_id,attempt_no,command_key,fingerprint,outcome,actor_employee_id,task_id,public_explanation,started_at,finished_at,request_id) SELECT ${identity('attempt','n')},refund_id,1,${identity('refund-command','n')},repeat('a',64),CASE WHEN n%20=0 THEN 'SUCCEEDED' ELSE 'FAILED' END,$1,task_id,'性能夹具模拟结果',created_at+interval '5 minutes',created_at+interval '5 minutes',${identity('refund-request','n')}::text FROM perf_rows WHERE n%20 IN(0,5)`,[employeeId]);
    await db.query(`UPDATE refund r SET status='SUCCEEDED',succeeded_at=p.created_at+interval '5 minutes',successful_attempt_id=${identity('attempt','p.n')} FROM perf_rows p WHERE r.id=p.refund_id AND p.n%20=0`);
    await db.query(`UPDATE after_sale a SET refund_id=p.refund_id,status=CASE WHEN p.n%20=0 THEN 'SUCCEEDED' ELSE 'REFUND_FAILED' END,closed_at=CASE WHEN p.n%20=0 THEN p.created_at+interval '5 minutes' END FROM perf_rows p WHERE a.id=p.sale_id AND p.n%20 IN(0,5)`);
    await db.query(`INSERT INTO audit_log(id,actor_type,actor_customer_id,action,target_type,target_id,request_id,created_at) SELECT ${identity('audit','n')},'CUSTOMER',customer_id,'order.create','Order',order_id::text,${identity('request','n')}::text,created_at FROM perf_rows`);
    await db.query(`INSERT INTO audit_business_reference(audit_log_id,business_type,business_id,business_no) SELECT ${identity('audit','n')},'ORDER',order_id::text,'PERF-O-'||n FROM perf_rows`);
    await db.query(`INSERT INTO business_state_history(id,aggregate_type,aggregate_id,dimension,command_key,to_state,actor_type,actor_employee_id,reason,public_text,request_id,created_at) SELECT ${identity('history','n')},'ORDER',$1,'performance-progress','perf-'||n,'WAIT_SHIPMENT','EMPLOYEE',$2,'性能历史分页夹具','性能历史公开摘要',${identity('history-request','n')}::text,now()-(n||' seconds')::interval FROM generate_series(1,200) n`,[performanceId('order',2),employeeId]);
    await db.query('COMMIT');await db.query('ANALYZE');
    const distribution=(await db.query('SELECT status,count(*)::int count FROM "order" GROUP BY status ORDER BY status')).rows;
    return {orders:100000,customers:1000,products:1000,skus:1000,payments:95000,refunds:10000,succeededRefunds:5000,failedRefunds:5000,audits:100000,references:100000,extraHistory:200,distribution};
  }catch(error){await db.query('ROLLBACK');throw error;}finally{await db.end();}
}
